"""Faster solver using eigvals only (no eigenvectors). Keep float64 for accuracy.
Expected to speed reference about ~2x, maybe less than 3x, but we can add other optimisations.
We need 3x.
"""

from __future__ import annotations

import numpy as np
import numpy.linalg as npl


def _sort_key(z: complex):
    return (-z.real, -z.imag)


class Solver:
    def solve(self, problem: np.ndarray, **kwargs) -> list[complex]:
        eigvals = npl.eigvals(problem)
        return sorted((complex(z) for z in eigvals), key=_sort_key)
