x=np.random.rand(n); y=3*x+2+0.3*np.random.randn(n); sx=0.05*np.random.rand(n)+0.05; sy=0.1*np.random.rand(n)+0.05

data=odr.RealData(x,y=y,sx=sx,sy=sy)

# baseline (finite diff)
model_fd = odr.Model(lambda B, x: B[0]*x+B[1])

def run_baseline():
    return odr.ODR(data, model_fd, beta0=[0,1]).run()

# analytic jacobians

def f(B, x):
    return B[0]*x + B[1]

def fjacb(B, x):
    return np.vstack((x, np.ones_like(x)))

def fjacd(B, x):
    # derivative wrt x: slope
    return B[0]*np.ones_like(x)

model_jac = odr.Model(f, fjacb=fjacb, fjacd=fjacd)

def run_jac():
    od=odr.ODR(data, model_jac, beta0=[0,1])
    od.set_job(deriv=3)  # user-supplied, no checking
    return od.run()

for fun in (run_baseline, run_jac):
    start=time.time();
    for _ in range(10): fun()
    print(fun.__name__, (time.time()-start)/10)
