task=Task()

def candidate_solve(problem, maxiter_factor, ncv):
    A=problem['matrix']; k=problem['k']; N=A.shape[0]
    v0=np.ones(N, dtype=A.dtype)
    vals, vecs = eigs(A, k=k, v0=v0, maxiter=N*maxiter_factor, ncv=ncv)
