from scipy.sparse.linalg import eigs

class FastSolver:
    def __init__(self, ncv=20, iter_factor=60):
        self.ncv=ncv; self.iter_factor=iter_factor
    def solve(self, problem):
        A=problem['matrix']; k=problem['k']; N=A.shape[0]
        v0=np.ones(N, dtype=A.dtype)
        vals, vecs=eigs(A,k=k,v0=v0,ncv=self.ncv,maxiter=N*self.iter_factor)
        idx=np.argsort(-np.abs(vals))
        vecs=vecs[:, idx]
        return [vecs[:, i] for i in range(k)]

def test(solver, trials=500):
    task=Task()
    for seed in random.sample(range(10**8), trials):
        problem=task.generate_problem(n=300, random_seed=seed)
        sol=solver.solve(copy.deepcopy(problem))
        if not task.is_solution(problem, sol):
            return False, seed
    return True, None

for iter_factor in [40, 50, 60, 80, 100]:
    for ncv in [15, 18, 20]:
