from reference import Task
from scipy.sparse.linalg import eigs, ArpackNoConvergence
logging.disable(logging.CRITICAL)

def solve_fast(problem, tol=1e-4, factor=20, ncv=20):
    A=problem['matrix']; k=problem['k']; N=A.shape[0]
    v0=np.ones(N)
    try:
        vals, vecs = eigs(A,k=k,v0=v0,ncv=ncv,maxiter=N*factor,tol=tol)
    except ArpackNoConvergence as err:
        if err.eigenvectors is not None and err.eigenvectors.shape[1]==k:
            vals, vecs = err.eigenvalues, err.eigenvectors
        else:
            vals, vecs = eigs(A,k=k,v0=v0,ncv=ncv,maxiter=N*200)
    pairs=list(zip(vals, vecs.T)); pairs.sort(key=lambda p: -abs(p[0]));
    return [p[1] for p in pairs]

task=Task()
for seed in random.sample(range(10**7), 1000):
    prob=task.generate_problem(300, seed)
    sol=solve_fast(copy.deepcopy(prob))
    if not task.is_solution(prob, sol):
        print('fail',seed)
        break
else:
    print('all good')
